extra_css:
/* watercolor blotches behind everything (fixed, so they do not scroll) */
.lia-canvas { background-image: radial-gradient(38rem 26rem at 12% 18%, rgba(232, 160, 160, 0.28), transparent 70%), radial-gradient(34rem 30rem at 88% 12%, rgba(156, 203, 217, 0.32), transparent 70%), radial-gradient(40rem 28rem at 78% 88%, rgba(243, 207, 138, 0.26), transparent 70%), radial-gradient(30rem 24rem at 20% 90%, rgba(185, 214, 164, 0.26), transparent 70%); background-attachment: fixed; }
:root.lia-variant-dark .lia-canvas { background-image: radial-gradient(38rem 26rem at 12% 18%, rgba(232, 160, 160, 0.10), transparent 70%), radial-gradient(34rem 30rem at 88% 12%, rgba(156, 203, 217, 0.12), transparent 70%), radial-gradient(40rem 28rem at 78% 88%, rgba(243, 207, 138, 0.08), transparent 70%); }
.lia-header, .lia-toc { background-color: transparent; }
/* painted gradient text for h1 */
.lia-slide__content :is(h1, .h1) { background: linear-gradient(100deg, #3d6f8f 0%, #b25c7a 55%, #d99a4e 100%); -webkit-background-clip: text; background-clip: text; color: transparent; }
:root.lia-variant-dark .lia-slide__content :is(h1, .h1) { background-image: linear-gradient(100deg, #9ccbd9 0%, #e8a0a0 55%, #f3cf8a 100%); }
/* drop cap on the first paragraph of a section */
.lia-slide__content > header + .lia-paragraph::first-letter { float: left; font-family: 'Playfair Display', serif; font-weight: 700; font-size: 3.4em; line-height: 0.8; margin: 0.08em 0.1em 0 0; color: rgb(var(--color-highlight-dark)); }
/* ornamental divider */
.lia-slide__content :is(hr, .lia-divider) { border: 0; height: auto; background: none; text-align: center; overflow: visible; }
.lia-slide__content :is(hr, .lia-divider)::after { content: '\2766'; display: inline-block; font-size: 2.4rem; color: rgba(var(--color-highlight), 0.7); }
/* frosted-glass quote over the blotches */
.lia-quote:not([class*='alert']) { background: rgba(255, 255, 255, 0.45); -webkit-backdrop-filter: blur(0.8rem) saturate(1.3); backdrop-filter: blur(0.8rem) saturate(1.3); border: 1px solid rgba(255, 255, 255, 0.7); }
:root.lia-variant-dark .lia-quote:not([class*='alert']) { background: rgba(255, 255, 255, 0.06); border-color: rgba(255, 255, 255, 0.12); }
.lia-quote__text { font-size: 2.4rem; font-weight: 500; }
/* scrapbook photos: white frame, soft shadow, slight tilt */
.lia-slide__content .lia-paragraph > img, .lia-slide__content figure:not(.lia-gallery figure) img { background: #fff; padding: 0.8rem 0.8rem 2.4rem; box-shadow: 0 0.6rem 1.6rem rgba(59, 52, 64, 0.18); transform: rotate(-1.5deg); }
.lia-slide__content .lia-paragraph img:nth-of-type(even) { transform: rotate(1.8deg); }
/* gallery: organic shapes painted into the paper (tiles are black by default) */
.lia-gallery .lia-figure__media { background: transparent; }
.lia-gallery img { border-radius: 58% 42% 55% 45% / 45% 55% 45% 55%; mix-blend-mode: multiply; }
:root.lia-variant-dark .lia-gallery img { mix-blend-mode: normal; opacity: 0.9; }
